        'actions_row1_does' => 'এই ওয়ার্কফ্লোর এক্সিকিউশন লগে একটি বার্তা লেখে। নিয়ম তৈরির সময় প্লেসহোল্ডার হিসেবে এবং ইঞ্জিন শুরু থেকে শেষ পর্যন্ত কাজ করছে কি না যাচাই করতে কাজে লাগে।',
        'actions_row1_args' => 'message',
        'actions_row2_does' => 'টিকিটের স্ট্যাটাস বদলায়। নতুন স্ট্যাটাসের <em>is_closed</em> ফ্ল্যাগ বদলালে নিজে থেকেই <code>closed_datetime</code> বসায় / মুছে দেয়।',
        'actions_row2_args' => 'ticket_id, status_id',
        'actions_row3_does' => 'টিকিটের অগ্রাধিকার ঠিক করে।',
        'actions_row3_args' => 'ticket_id, priority_id',
        'actions_row4_does' => 'টিকিটের মালিক / নিযুক্ত ব্যক্তি ঠিক করে। <code>assigned_analyst_id</code> ও <code>owner_id</code> দুটোই হালনাগাদ করে, যাতে ডান প্যানের মালিক ফিল্ড মিলে থাকে।',
        'actions_row4_args' => 'ticket_id, analyst_id',
        'actions_row5_does' => 'টিকিটের অডিট ট্রেইলে একটি ফ্রি-টেক্সট নোট যোগ করে। অভ্যন্তরীণ &mdash; অনুরোধকারীকে কখনো পাঠানো হয় না।',
        'actions_row5_args' => 'ticket_id, note',
        'actions_row6_does' => 'টিকিটের মেইলবক্স ব্যবহার করে টিকিটের অনুরোধকারীকে (বা যেকোনো ঠিকানায়) ইমেল পাঠায়। বিষয়ের শুরুতে <code>[SDREF:&hellip;]</code> বসে, ফলে উত্তরগুলো নিজে থেকেই থ্রেডে জোড়া লাগে। <strong>টিকিট এখন ঐচ্ছিক</strong> &mdash; বদলে পাঠানোর মেইলবক্স বেছে নিন; এভাবেই কোনো টিকিট তৈরির আগে ফর্ম জমার প্রাপ্তিস্বীকার করা যায়। টিকিট না থাকলে উত্তর জোড়া লাগার কিছু থাকে না, তাই কোথাও না পৌঁছানো উত্তরের আমন্ত্রণ না জানিয়ে &ldquo;এই লাইনের উপরে উত্তর দিন&rdquo; চিহ্নটি বাদ দেওয়া হয়।',
        'actions_row6_args' => 'ticket_id, to, subject, body',
        'actions_row7_does' => 'একটি কাজ তৈরি করে। <code>ticket_id</code> দিলে উৎস টিকিটের সাথে নিজে থেকেই যুক্ত হয়। স্ট্যাটাস / অগ্রাধিকার ফাঁকা থাকলে ওয়ার্কস্পেসের ডিফল্ট ব্যবহার হয়।',
        'actions_row7_args' => 'title, description, status_id, priority_id, assignee_id, ticket_id',
        'actions_row8_does' => 'একটি নতুন টিকিট তৈরি করে। <em>"নতুন-সদস্য ফর্ম &rarr; IT + HR + Facilities টিকিট"</em>-এর মতো ছড়িয়ে দেওয়া ওয়ার্কফ্লোয় কাজে লাগে। ইভেন্টে <strong>ফর্ম জমা</strong> থাকলে টিকিটটি নিজে থেকেই সঠিক পদ্ধতিতে তৈরি হয় &mdash; অনুরোধকারী তার আসল অ্যাকাউন্টের সাথে মেলানো হয়, কোম্পানি সেখান থেকে নেওয়া হয়, আর বডি ফাঁকা রাখলে জমা দেওয়া উত্তরগুলো টেবিল আকারে সাজানো হয়। এখানে আপনি যা-ই ঠিক করবেন সেটাই প্রাধান্য পায়; ফর্ম শুধু আপনার ফাঁকা রাখা অংশ পূরণ করে।',
        'actions_row8_args' => 'subject, body, priority_id, department_id, type_id, assigned_analyst_id, from_email, from_name',
        'actions_row9_does' => 'একটি বাইরের URL-এ বার্তা POST করে &mdash; Slack, Teams, Discord, PagerDuty, Zapier/Make বা ইনকামিং ওয়েবহুক গ্রহণ করে এমন যেকোনো সিস্টেমে ইভেন্ট পাঠান। একটি চ্যাট প্রিসেট বেছে নিন, সম্পূর্ণ রেকর্ড পাঠান (পুরো অবজেক্ট JSON হিসেবে, REST API-র মতোই), অথবা নিজের কাস্টম JSON বডির টেমপ্লেট বানান। ঐচ্ছিক HMAC সাইনিং সিক্রেট সমর্থন করে, এবং একটি টেস্ট পাঠান বোতাম আছে যা সংরক্ষণের আগে এন্ডপয়েন্টের আসল প্রতিক্রিয়া দেখায়।',
        'actions_row9_args' => 'preset, url, message (presets), body (custom JSON), secret (optional)',
        'actions_note' => 'প্রতিটি অ্যাকশনের আবশ্যক আর্গুমেন্ট ফর্মে <code>*</code> দিয়ে চিহ্নিত থাকে। আবশ্যক আর্গুমেন্ট না থাকলে এক্সিকিউশনের সময় অ্যাকশন ব্যর্থ হয় &mdash; ইঞ্জিন এক্সিকিউশন সারিতে ব্যর্থতা লগ করে এবং শৃঙ্খলের বাকি অংশ থামিয়ে দেয়।',
        'actions_webhook_callout' => '<strong><code>send_webhook</code> অ্যাকশন নিজেই একটি বড় বিষয়</strong> &mdash; চ্যাট প্রিসেট, পুরো অবজেক্টের &ldquo;সম্পূর্ণ রেকর্ড&rdquo; পেলোড, HMAC সাইনিং, টেস্ট পাঠান বোতাম, রিট্রাইসহ ব্যাকগ্রাউন্ড ডেলিভারি এবং একটি হেলথ ড্যাশবোর্ড। এর জন্য আলাদা নির্দেশিকা আছে: <a href="help-webhooks.php"><strong>ওয়েবহুক নির্দেশিকা &rarr;</strong></a>',
        'variables_heading' => 'ভেরিয়েবল &mdash; <code>{{path.to.field}}</code>',
        'variables_intro' => 'যেকোনো ফ্রি-টেক্সট অ্যাকশন আর্গুমেন্ট তাকে চালু করা ইভেন্ট থেকে মান টেনে আনতে পারে। কোড হাতে টাইপ করতে হবে না: ভেরিয়েবল-উপযোগী প্রতিটি ফিল্ডে একটি <strong>ভেরিয়েবল দিয়ে সম্পাদনা</strong> বোতাম আছে, যা একটি প্রশস্ত এডিটর খোলে, যার পাশে আছে <strong>খোঁজা যায় এমন ভেরিয়েবলের তালিকা</strong> — একটিতে ক্লিক করলে সেটি কার্সারের জায়গায় বসে যায়। লাইভ প্রিভিউ সমাপ্ত টেক্সট দেখায়, যেখানে প্রতিটি কোড তার আসল মান দিয়ে বদলানো।',
        'variables_scoped' => '<strong>আপনাকে শুধু সেই ভেরিয়েবলই দেওয়া হয় যা ট্রিগার সত্যিই পূরণ করতে পারে।</strong> এটি যতটা মনে হয় তার চেয়ে বেশি গুরুত্বপূর্ণ: অনুপস্থিত ভেরিয়েবল কোনো ত্রুটি দেখায় না, চুপচাপ একটি <em>খালি স্ট্রিং</em> হয়ে যায়। তাই <code>knowledge.published</code>-এর ওয়ার্কফ্লোর বার্তায় <code>{{ticket.subject}}</code> থাকলে সেটি ব্যর্থ হতো না — বিষয়ের জায়গায় শুধু একটি ফাঁকা বসিয়ে দিত, আর আপনি কখনো জানতেন না। নলেজ ইভেন্টে কোনো টিকিট নেই, তাই পিকার টিকিট ভেরিয়েবল দেয়ই না, আর আপনি তবু টাইপ করলে ফিল্ডটি সতর্ক করে যে এটি ফাঁকা আসবে।',
        'variables_names' => '<strong>আইডি নয়, নাম ব্যবহার করুন।</strong> <code>{{ticket.priority_id}}</code> দেখায় <code>4</code> &mdash; একটি সংখ্যা, যা আপনার Slack চ্যানেলের কেউ বুঝবে না। তাই প্রতিটি লুকআপ ফিল্ডের একটি পাঠযোগ্য জোড়া আছে: <code>{{ticket.priority_name}}</code> দেখায় <strong>Critical</strong>। পিকার নামটিকে সাধারণ বিকল্প হিসেবে দেখায় (<em>টিকিট &middot; অগ্রাধিকার</em>) এবং সংখ্যারটিকে <em>(id)</em> চিহ্ন দেয়, কারণ মানুষ যে বার্তা পড়বে তাতে প্রায় সবসময় নামটাই লাগে। প্রয়োজনে আইডিও আছে &mdash; শর্তের জন্য, অথবা যে গ্রহণকারী সিস্টেম আইডি আশা করে তার জন্য। পরিবর্তন ট্রিগারে <code>{{old_priority_name}}</code> / <code>{{new_priority_name}}</code>-ও পাবেন, ফলে "High থেকে Critical-এ উন্নীত" লেখা সহজেই হয়ে যায়।',
        'variables_number' => '<strong>সারির আইডি নয়, রেফারেন্স উল্লেখ করুন।</strong> <code>{{ticket.id}}</code> হলো ভেতরের ডেটাবেস আইডি (<code>83</code>) &mdash; অনুরোধকারীর কাছে অর্থহীন। <code>{{ticket.number}}</code> হলো সেই রেফারেন্স যা তারা আপনাকে আসলে উল্লেখ করে (<code>ETC-623-64409</code>), এবং ইমেলের বিষয়ে বা চ্যাট অ্যালার্টে এটিই মানানসই। <code>{{problem.number}}</code>-এর ক্ষেত্রেও একই। <strong>একটি ব্যতিক্রম:</strong> <em>টিকিট আইডি</em> অ্যাকশন আর্গুমেন্ট অবশ্যই <code>{{ticket.id}}</code> থাকতে হবে &mdash; এই ফিল্ড ইঞ্জিনকে বলে <em>কোন রেকর্ডে কাজ করতে হবে</em>, আর সে সারির আইডি দিয়ে খোঁজে। মানুষ যে লেখা পড়ে তাতে নম্বর ব্যবহার করুন; ভেতরের কাঠামোতে আইডি রাখুন।',
        'variables_full' => 'ট্রিগার যেখানে পুরো রেকর্ড বহন করে, সেখানে <code>{{&lt;object&gt;.full}}</code>-ও পাবেন &mdash; যেমন <code>{{ticket.full}}</code> &mdash; যা REST API যে আকৃতিতে রেকর্ড ফেরত দেয় ঠিক সেই আকৃতিতে পুরো রেকর্ডটি JSON হিসেবে বসায়। আর <code>{{event}}</code> সবসময় চালু হওয়া ট্রিগারের নামে রূপান্তরিত হয়।',
        'variables_common' => 'টিকিট ট্রিগারের সাধারণ ভেরিয়েবল:',
        'variables_li1' => '<code>{{ticket.id}}</code>, <code>{{ticket.subject}}</code>, <code>{{ticket.priority_id}}</code>, <code>{{ticket.status_id}}</code>',
        'variables_li2' => '<code>{{ticket.department_id}}</code>, <code>{{ticket.type_id}}</code>, <code>{{ticket.assigned_analyst_id}}</code>',
        'variables_li3' => '<code>{{ticket.owner_id}}</code>, <code>{{ticket.created_by}}</code>, <code>{{ticket.requester_email}}</code>',
        'variables_li4' => '<code>ticket.status_changed</code> / <code>ticket.priority_changed</code>-এর জন্য আরও: <code>{{old_status_id}}</code>, <code>{{new_status_id}}</code>, <code>{{old_priority_id}}</code>, <code>{{new_priority_id}}</code>',
        'variables_li5' => '<code>ticket.assigned</code>-এর জন্য আরও: <code>{{analyst_id}}</code>, <code>{{team_id}}</code>',
        'variables_tip' => '<strong>সেরা চর্চা:</strong> অ্যাকশনের <code>ticket_id</code> ফিল্ডে নির্দিষ্ট আইডি টাইপ না করে ডিফল্ট <code>{{ticket.id}}</code> রেখে দিন &mdash; এতে ওয়ার্কফ্লো স্থির কোনো টিকিটে নয়, যে টিকিট এটি চালু করেছে সেটিতেই কাজ করে।',
        'variables_chain_heading' => 'আগের অ্যাকশনের ফলাফল ব্যবহার করা',
        'variables_chain_intro' => 'অ্যাকশনগুলো ক্রমানুসারে চলে, এবং পরেরটি আগেরটির কাজের কথা উল্লেখ করতে পারে। এর ফলেই <em>&ldquo;একটি টিকিট তৈরি করুন, তারপর ব্যক্তিকে তার টিকিট নম্বর ইমেল করুন&rdquo;</em> অসম্ভব না হয়ে একটিই ওয়ার্কফ্লো হয়।',
        'variables_chain_last' => '<code>{{last.ticket_id}}</code> &mdash; এর ঠিক আগের অ্যাকশন যা তৈরি করেছে।',
        'variables_chain_steps' => '<code>{{steps.1.ticket_number}}</code> &mdash; ক্যানভাসে পাশে দেখানো নম্বর দিয়ে নির্দিষ্ট একটি অ্যাকশন। আপনি যেটি চান সেটি সরাসরি আগেরটি না হলে এটি ব্যবহার করুন।',
        'variables_chain_note' => 'এগুলো ইচ্ছে করেই নিজস্ব নামে থাকে, ওয়ার্কফ্লোর নিজের ডেটা ওভাররাইট করে না। টিকিট তৈরি যদি <code>{{ticket.id}}</code> বদলে দিত, টিকিট ওয়ার্কফ্লোর পরবর্তী প্রতিটি ধাপ চুপচাপ ওয়ার্কফ্লো চালু করা টিকিটের বদলে নতুন টিকিটের দিকে ইঙ্গিত করত।',
        'actions_forms_callout' => '<strong>ফর্মও এই অ্যাকশনগুলো চালাতে পারে।</strong> ওয়ার্কফ্লো না বানিয়ে একটি ফর্ম খুলুন এবং এর <strong>এরপর কী ঘটবে</strong> ট্যাবে বলে দিন ফর্ম জমা, অনুমোদিত বা প্রত্যাখ্যাত হলে কী হবে। ইঞ্জিন একই, অ্যাকশনও একই, আর রানগুলো একই এক্সিকিউশন লগে দেখা যায় &mdash; ফর্ম এডিটর শুধু ঢোকার দ্বিতীয় পথ, যা সেই একটি ফর্মের মধ্যে সীমাবদ্ধ। কোনো নিয়ম একাধিক ফর্মজুড়ে খাটলে এখানে ওয়ার্কফ্লো বানান।',
        'ai_heading' => 'AI সহ-লেখক',
        'ai_intro' => 'টুলবারে <strong>AI সহ-লেখক</strong>-এ ক্লিক করে সহজ ভাষায় ওয়ার্কফ্লোটি বর্ণনা করুন। AI একটি কাঠামোবদ্ধ প্রস্তাব ফেরত দেয় &mdash; ট্রিগার, শর্ত, অ্যাকশন &mdash; যা আপনি ক্যানভাসে <em>প্রয়োগ</em> বা <em>বাতিল</em> করতে পারেন।',
        'ai_examples' => 'যেসব উদাহরণ ভালো কাজ করে:',
        'ai_ex1' => '<em>"Critical অগ্রাধিকারের টিকিট তৈরি হলে একটি নোট যোগ করো: \'P1 &mdash; please respond within 15 minutes\'।"</em>',
        'ai_ex2' => '<em>"<code>finance@acme.com</code> থেকে টিকিট তৈরি হলে সেটি আমাকে বরাদ্দ করো এবং অগ্রাধিকার High করো।"</em>',
        'ai_ex3' => '<em>"টিকিট বন্ধ হলে অনুরোধকারীকে ধন্যবাদ জানিয়ে এবং মতামত চেয়ে একটি ইমেল পাঠাও।"</em>',
        'ai_catalogue' => 'AI ইঞ্জিনের পুরো তালিকা জানে &mdash; প্রতিটি ট্রিগার, শর্তের অপারেটর, অ্যাকশন এবং লুকআপ টেবিলের উপলব্ধ মান &mdash; তাই সে শুধু এমন কিছুই প্রস্তাব করতে পারে যা সত্যিই কাজ করবে। বিদ্যমান ওয়ার্কফ্লো ধরে এগোলে (<em>"এখন শুধু Finance মিলাও"</em> / <em>"টিকিট আইডি লগ করার একটি অ্যাকশন যোগ করো"</em>) সে নতুন করে শুরু না করে ক্যানভাসে যা আছে তা সম্পাদনা করে।',
        'ai_config' => '<strong>ওয়ার্কফ্লো &rarr; সেটিংস &rarr; AI</strong>-এর অধীনে প্রোভাইডার (Anthropic / OpenAI), মডেল ও API key কনফিগার করুন। key মডিউল অনুযায়ী আলাদাভাবে রাখা হয়, ফলে বিলিং ও অ্যাক্সেস সূক্ষ্মভাবে নিয়ন্ত্রণ করা যায়।',
        'templates_heading' => 'টেমপ্লেট থেকে শুরু করুন',
        'templates_intro' => 'ওয়ার্কফ্লো তালিকার <strong>টেমপ্লেট থেকে নতুন</strong> বোতামটি তৈরি-করা রেসিপির একটি গ্যালারি খোলে, যা বেশিরভাগ সার্ভিস ডেস্ক সবার আগে স্বয়ংক্রিয় করে &mdash; নতুন টিকিটের স্বয়ংক্রিয় প্রাপ্তিস্বীকার, P1-এ দলকে সতর্ক করা, নতুন-সদস্য ফর্মকে IT, HR ও Facilities টিকিটে ছড়িয়ে দেওয়া, পরিবর্তন অনুমোদিত হলে বাস্তবায়নের কাজ তৈরি করা। এর মধ্যে চারটি <strong>সময়-ভিত্তিক</strong>: SLA ভাঙার <em>আগে</em> টিকিট এসকেলেট করা, ভাঙলে সতর্ক করা, এবং কোনো চুক্তি বা অ্যাসেটের ওয়ারেন্টি শেষ হতে চলেছে তা মনে করিয়ে দেওয়া। একটি বেছে নিলে সেটি একটি সাধারণ, সম্পূর্ণ সম্পাদনাযোগ্য ওয়ার্কফ্লো হিসেবে আপনার ওয়ার্কফ্লোতে কপি হয়ে যায়। এরপর এতে বিশেষ কিছু থাকে না: নাম বদলানো, নতুন করে সাজানো বা মুছে ফেলা আপনার হাতে। গ্যালারি <strong>বিভাগ</strong> ও <strong>অনুসন্ধান</strong> দিয়ে ফিল্টার হয় &mdash; অনুসন্ধান বিবরণ, ট্রিগার ও অ্যাকশন পর্যন্ত পৌঁছায়, তাই <em>expiry</em>, <em>slack</em> বা <em>wipe</em> লিখলে নামে শব্দটি না থাকলেও রেসিপিটি পাওয়া যায়।',
        'templates_lookups' => 'প্রতিটি ইনস্টল নিজের স্ট্যাটাস ও অগ্রাধিকারের নাম দেয়, তাই টেমপ্লেট সেগুলো সরাসরি লিখে রাখতে পারে না। বদলে সে বলে <em>"এই ইনস্টল যাকে Closed বলে"</em>, আর কপি করার সময় আমরা আসল মানটি খুঁজে নিই। যা আমরা মেলাতে পারি না &mdash; আপনার নেই এমন অগ্রাধিকার, অথবা শুধু আপনি জানেন এমন মান, যেমন Slack ওয়েবহুক URL &mdash; তা ফাঁকা রাখা হয় এবং এডিটরের উপরে একটি ব্যানারে তালিকাভুক্ত করা হয়, ফলে ঠিক কী কী এখনো আপনার করার বাকি তা দেখতে পাবেন।',
        'templates_scheduled' => 'চারটি সময়-ভিত্তিক রেসিপি চলতে একটি <strong>শিডিউলড টাস্ক</strong> লাগে, কারণ এরা যা দেখে তার কিছুই ইভেন্ট নয় &mdash; SLA চুপচাপ সময় ফুরিয়ে ফেললে কেউ কিছু সংরক্ষণ করে না, তাই একটি কাজকে গিয়ে খুঁজতে হয়। ক্রন শিডিউল না থাকলে এই ওয়ার্কফ্লোগুলো সক্রিয় অবস্থায় পড়ে থাকে, কখনো চলে না। দুটি মেয়াদ-শেষের রিমাইন্ডার <strong>৯০, ৩০, ৭ ও ১ দিন</strong> আগেও চলে, আর প্রতিটি রেসিপি ৩০ দিনেরটিতে ফিল্টার করা &mdash; প্রতিটি ধাপে জানতে চাইলে সেই শর্ত বদলান বা বাদ দিন। দেখুন <a href="#triggers">ট্রিগার</a>।',
        'templates_callout' => 'কপি করা টেমপ্লেট সবসময় <strong>বন্ধ অবস্থায়</strong> আসে। আপনি পড়ে, ফাঁক পূরণ করে <em>সক্রিয়</em>-তে টিক না দেওয়া পর্যন্ত এর কিছুই চালু হতে পারে না &mdash; এবং আগে <strong>ড্রাই রান</strong> করে দেখে নিতে পারেন এটি ঠিক কী করবে।',
        'testing_heading' => 'সংরক্ষণ ও পরীক্ষা',
        'testing_save' => 'টুলবারের স্ট্যাটাস পিপ দেখায় <em>অসংরক্ষিত</em> / <em>সংরক্ষণ হচ্ছে&hellip;</em> / <em>সংরক্ষিত</em>। স্থায়ী করতে <strong>সংরক্ষণ</strong>-এ ক্লিক করুন। শূন্য অ্যাকশনসহ অসমাপ্ত খসড়াও সংরক্ষণ করা যায় &mdash; আটকে না দিয়ে আপনি একটি হালকা সতর্কবার্তা পাবেন "এই ওয়ার্কফ্লোতে এখনো কোনো অ্যাকশন নেই"।',
        'testing_dry_heading' => 'ড্রাই রান &mdash; না করেই দেখুন কী করত',
        'testing_dry_body' => '<strong>ড্রাই রান</strong> শর্তগুলো সত্যিই যাচাই করে, তারপর প্রতিটি অ্যাকশন চালানোর বদলে তার <em>বর্ণনা</em> দেয়। রানটি <em>সাম্প্রতিক রান</em>-এ <em>ড্রাই রান</em> চিহ্নসহ দেখা যায়, আর তালিকায় থাকে সে যা যা করত &mdash; <code>{{variables}}</code> আগে থেকেই ভরা অবস্থায়, ফলে আপনি আসল ইমেলের বিষয়, আসল চ্যাট বার্তা, আসল নোট পড়তে পান।',
        'testing_dry_safe' => 'কিছুই লেখা, ইমেল করা, সারিতে রাখা বা পাঠানো হয় না: কোনো টিকিট বদলায় না, কোনো নোট যোগ হয় না, কোনো ওয়েবহুক ডেলিভারি হয় না, আর ওয়ার্কফ্লোর রান কাউন্টার অপরিবর্তিত থাকে। তাই চালু ওয়ার্কফ্লোতেও এটি নিরাপদে চালানো যায় &mdash; এবং সদ্য কপি করা টেমপ্লেটে এটিই প্রথম করণীয়। (যেকোনো সাইনিং সিক্রেট আউটপুটে প্রতিধ্বনি না করে ঢেকে দেওয়া হয়।)',
        'testing_log_heading' => 'এক্সিকিউশন লগ &mdash; আসলে যা ঘটেছে',
        'testing_log_why' => 'এটি যতটা মনে হয় তার চেয়ে বেশি গুরুত্বপূর্ণ। ইঞ্জিন <strong>ইচ্ছে করেই নিজের ত্রুটি গিলে ফেলে</strong> &mdash; ভাঙা ওয়ার্কফ্লো যেন কখনো তাকে চালু করা টিকিট সংরক্ষণ নষ্ট না করে। সিদ্ধান্তটি ঠিক, কিন্তু এর মানে ব্যর্থ ওয়ার্কফ্লো অন্যথায় <em>পুরোপুরি নীরব</em>। কেউ আপনাকে জানায় না। এই নীরবতা ভাঙে এক্সিকিউশন লগ এবং <strong>ওয়াচটাওয়ারের ওয়ার্কফ্লো কার্ড</strong> (যা গত ২৪ ঘণ্টার ব্যর্থতা, লুপ-সুরক্ষায় বাতিল এবং রিট্রাই ছেড়ে দেওয়া ওয়েবহুক তুলে ধরে)।',
        'testing_fire_heading' => 'টেস্ট ফায়ার &mdash; সত্যিই চালান',
        'testing_fire' => '<strong>টেস্ট ফায়ার</strong> ওয়ার্কফ্লোর নিজের শর্ত থেকে তৈরি একটি কৃত্রিম পেলোড দিয়ে সেটি সত্যিই চালায়, ফলে অ্যাকশনের পথ আসলেই কার্যকর হয় &mdash; ওই ইমেল সত্যিই পাঠানো হবে। ফলাফল <em>সাম্প্রতিক রান</em>-এ স্ট্যাটাস (<em>সফল / ব্যর্থ / বাদ</em>) ও সম্পূর্ণ ধাপ লগসহ জমা হয়।',
        'testing_real' => 'প্রকৃত ডেটা দিয়ে পরীক্ষা করতে, যা ট্রিগারটি চালু করে সেটাই করুন &mdash; একটি টিকিট বরাদ্দ করুন, তার অগ্রাধিকার পরিবর্তন করুন ইত্যাদি। হোস্ট মডিউল (টিকিট) থেকে ডিসপ্যাচ চালু আছে; এক্সিকিউশন লগে প্রতিটি ফায়ার দেখা যায়।',
        'triggers_heading' => 'ট্রিগার ক্যাটালগ',
        'triggers_intro' => 'ক্যাটালগটি এখন <strong>প্রতিটি মডিউল জুড়ে &mdash; ১৩৮টি ট্রিগার এবং বাড়ছে</strong>, সবগুলো সংযুক্ত ও চালু। এগুলো দুই ধরনের:',
        'triggers_time_heading' => 'সময়ভিত্তিক ট্রিগার &mdash; এবং যে cron লাগে',
        'triggers_time_body' => 'বেশিরভাগ ট্রিগার একটি <strong>লেখার পথ</strong> থেকে ফায়ার হয়: কেউ একটি টিকিট সংরক্ষণ করেছে, তাই ফায়ার করার একটি মুহূর্ত আছে। চারটির ক্ষেত্রে তা নেই। <code>sla.warning</code>, <code>sla.breached</code>, <code>contract.expiring</code> এবং <code>asset.warranty_expiring</code> আদৌ কোনো ইভেন্ট নয় &mdash; <em>কিছু ঘটেনি, সময় পেরিয়েছে</em> &mdash; তাই একটি নির্ধারিত জবকে খুঁজে দেখতে হয়।',
        'triggers_time_cron' => '<strong>এই cron-গুলো নির্ধারিত না থাকলে এই ট্রিগারগুলো কখনোই ফায়ার হবে না।</strong> ওয়ার্কফ্লো সক্রিয় অবস্থায় পড়ে থাকবে, কিছুই করবে না। SLA ইভেন্ট আসে SLA লঙ্ঘন-পরীক্ষার cron থেকে (প্রতি ৫ মিনিটে); মেয়াদ-শেষের ইভেন্ট আসে <code>cron/workflow_scheduled.php</code> থেকে (ঘণ্টায় একবারই যথেষ্ট)। সেটআপ: <code>docs/workflow-scheduled-cron-setup.md</code>, অথবা <a href="https://github.com/edmozley/freeitsm/wiki/Time-Based-Triggers" target="_blank" rel="noopener noreferrer">উইকিতে Time-Based Triggers</a>, যেখানে এটিও ব্যাখ্যা করা আছে কেন একটি এখনও-সত্য শর্ত (লঙ্ঘিত SLA লঙ্ঘিতই থাকে) প্রতি কয়েক মিনিটে আবার ফায়ার হয় না।',
        'triggers_time_once' => 'একটি সময়ভিত্তিক শর্ত <strong>সত্য থেকে যায়</strong> &mdash; লঙ্ঘিত SLA পাঁচ মিনিট পরেও লঙ্ঘিত &mdash; তাই FreeITSM একটি খতিয়ান রাখে এবং প্রতিটি পরিস্থিতি <strong>ঠিক একবার</strong> ফায়ার হয়। এর নিচের বিষয়টি বদলালে এটি আবার প্রস্তুত হয়: কোনো টিকিটের অগ্রাধিকার বাড়ালে তার SLA লক্ষ্য ছোট হয়ে যায়, ফলে নতুন, কড়া সময়সীমা আবার এসকেলেট করতে পারে। একটি চুক্তি নবায়ন করলে আগামী বছরের রিমাইন্ডারও ফায়ার হবে। মেয়াদ-শেষের ইভেন্ট ফায়ার হয় <strong>৯০, ৩০, ৭ ও ১ দিন</strong> আগে, প্রতিটিতে থাকে <code>window_days</code> &mdash; তাই "শুধু ৩০ দিনে মনে করিয়ে দাও" একটি শর্ত মাত্র।',
        'triggers_family_domain' => '<strong>সমৃদ্ধ ডোমেইন ইভেন্ট</strong> &mdash; পূর্ণ টাইপযুক্ত পেলোডসহ অর্থপূর্ণ জীবনচক্রের মুহূর্ত: <code>ticket.created</code>, <code>ticket.status_changed</code>, <code>change.approved</code>, <code>problem.status_changed</code>, <code>task.completed</code>, <code>project.health_changed</code>, <code>service_status.incident_resolved</code>, <code>software.application_discovered</code>, এবং আরও অনেক।',
        'triggers_family_forms' => '<strong>ফর্ম ও ক্যাটালগ অনুরোধ</strong> &mdash; সাধারণ ফর্মের জন্য <code>form.submitted</code> ফায়ার হয়। অনুমোদন লাগে এমন ফর্মের জন্য এর বদলে <code>catalogue_request.submitted</code> ফায়ার হয়, তারপর আপনার অনুমোদনকারী সিদ্ধান্ত নিলে <code>catalogue_request.approved</code> বা <code>catalogue_request.rejected</code>। আলাদা ইভেন্টটি ইচ্ছাকৃত: এর ফলে জমা দেওয়ার সময় টিকিট তৈরি করে এমন নিয়ম আপনার চাওয়া অনুমোদন এড়িয়ে যেতে পারে না। চারটিতেই জমা দেওয়া উত্তর থাকে, তাই প্রতিটি ধাপে <code>{{submission.fields.Device type}}</code> কাজ করে, এবং চারটিকেই একটি নির্দিষ্ট ফর্মে সীমিত করা যায়।',
        'triggers_family_crud' => '<strong>তৈরি / হালনাগাদ / মুছে ফেলার ইভেন্ট</strong> &mdash; প্রতিটি পুনর্ব্যবহারযোগ্য রেকর্ড ও সেটিংস লুকআপ <code>&lt;entity&gt;.created</code> / <code>.updated</code> / <code>.deleted</code> পাঠায়: টিকিট, অ্যাসেট, পরিবর্তন, সমস্যা, কাজ, CMDB, চুক্তি ও সরবরাহকারী, ক্যালেন্ডার, সফটওয়্যার লাইসেন্স, নেটওয়ার্ক ডায়াগ্রাম, এবং তাদের সমস্ত সেটিংস তালিকা (স্ট্যাটাস, অগ্রাধিকার, ধরন, ট্যাগ&hellip;)।',
        'triggers_picker' => 'তালিকাটি কয়েক ডজন লম্বা বলে এডিটরের <strong>ট্রিগার পিকার অনুসন্ধানযোগ্য</strong> &mdash; ফিল্টার করতে টাইপ করা শুরু করুন (<code>resolved</code>, <code>contract</code>, <code>delete</code>&hellip;)। প্রতিটি ইভেন্ট <strong>একটিমাত্র শেয়ার্ড লেখার পথ</strong> থেকে ফায়ার হয়, তাই পরিবর্তনটি ব্রাউজার, REST API বা অন্য কোনো ওয়ার্কফ্লো যেখান থেকেই আসুক, আচরণ একই &mdash; এটি আলাদা হয়ে যেতে পারে না।',
        'failures_heading' => 'ইঞ্জিনের ব্যর্থতা আলাদা রাখা হয়',
        'failures_callout' => '<strong>একটি ত্রুটিপূর্ণ ওয়ার্কফ্লো হোস্ট মডিউলের অনুরোধ নষ্ট করতে পারে না।</strong> প্রতিটি ডিসপ্যাচ try/catch-এ মোড়ানো এবং প্রতিটি অ্যাকশনের ব্যর্থতা চেইন না থামিয়ে এক্সিকিউশন সারিতে লগ হয়। কোনো ওয়ার্কফ্লো আপনার প্রত্যাশামতো কাজ না করলে ওয়ার্কফ্লোর <em>সাম্প্রতিক রান</em> প্যানেল দেখুন &mdash; ব্যর্থতাগুলো সেখানে মূল ত্রুটিসহ দেখা যায়, যে পাতাটি সেগুলো চালু করেছিল সেখানে 500 হিসেবে নয়।',
        'ahead_heading' => 'সামনে যা আছে',
        'ahead_li1' => '<strong>টিয়ার ৩ অ্যাকশন</strong> &mdash; Microsoft Graph: <code>graph_add_to_group</code>, <code>graph_assign_license</code>, <code>graph_disable_user</code>। নতুন-যোগদানকারী / ছেড়ে-যাওয়া স্বয়ংক্রিয়করণ, যা মডিউলটিকে পেইড ITSM স্যুটের তুলনায় অনন্য করে। বিদ্যমান টেন্যান্ট OAuth কাঠামো পুনরায় ব্যবহার করে।',
        'ahead_li4' => '<strong>ড্রাই-রান মোড</strong> &mdash; একটি প্রকৃত ইভেন্টের বিপরীতে ওয়ার্কফ্লো চালান, কিন্তু অ্যাকশনগুলো সম্পাদন না করে <em>লগ</em> করুন। ফলে চালু করার আগে কী ঘটত তা দেখে নিতে পারবেন।',
        'ahead_li5' => '<strong>স্টার্টার রেসিপি</strong> &mdash; সাধারণ প্যাটার্নের ক্লোন করা যায় এমন টেমপ্লেট: নতুন-যোগদানকারীর অনবোর্ডিং, P1 ঘটনা সাড়া, SLA-লঙ্ঘন এসকেলেশন, লাইসেন্স-নবায়ন রিমাইন্ডার।',
        'ahead_li6' => '<strong>ওয়াচটাওয়ার ইন্টিগ্রেশন</strong> &mdash; ব্যর্থ রানগুলো মনোযোগ-কার্ড হিসেবে দেখা যাবে।',
        'ahead_li7' => '<strong>ওয়ার্কফ্লো ভার্সনিং</strong> &mdash; খসড়া / প্রকাশ / রোলব্যাক।',
        'ahead_li8' => '<strong>স্ট্রিমিং AI সহ-লেখক</strong> &mdash; ক্যানভাস তৈরি হওয়ার সাথে সাথে claude.ai-স্টাইলের লাইভ আউটপুট।',
    ],
];
